def carry_weeks_over(apps, schema_editor):
    """Saved weeks become weekly captures, and every existing list keeps its Monday
    save as a weekly tracker. A week was stored as a date: its period is that date's
    midnight to the next Monday's, in the site's time zone."""
    from datetime import datetime, time, timedelta

    from django.utils import timezone

    ContentType = apps.get_model("contenttypes", "ContentType")
    GoalList = apps.get_model("smallstack_dashboards", "GoalList")
    GoalSnapshot = apps.get_model("smallstack_dashboards", "GoalSnapshot")
    Snapshot = apps.get_model("smallstack_dashboards", "Snapshot")
    SnapshotTracker = apps.get_model("smallstack_dashboards", "SnapshotTracker")
    subject_type, _created = ContentType.objects.get_or_create(app_label="smallstack_dashboards", model="goallist")
    zone = timezone.get_current_timezone()

    def midnight(day):
        return timezone.make_aware(datetime.combine(day, time.min), zone)

    for old in GoalSnapshot.objects.all():
        new = Snapshot.objects.create(
            subject_type=subject_type,
            subject_id=old.goal_list_id,
            cadence="weekly",
            period_start=midnight(old.week_start),
            period_end=midnight(old.week_start + timedelta(weeks=1)),
            rows=old.rows,
            summary=old.summary,
            complete=old.complete,
            taken_by_id=old.taken_by_id,
        )
        Snapshot.objects.filter(pk=new.pk).update(taken_at=old.taken_at)  # auto_now_add set it to now
    for pk in GoalList.objects.values_list("pk", flat=True):
        SnapshotTracker.objects.create(subject_type=subject_type, subject_id=pk, cadence="weekly")


